window.products.push({"id":587446,"name":"Whitmor Over the Door Shoe Shelves","category":"homeandappliances","retail price":22.1,"sale price":null,"image":"https://m.media-amazon.com/images/I/71WQzOsQGnL._AC_SL1500_.jpg","description":"Whitmor's 26 Pocket Over the Door Shoe Shelves offers the best way to organize and see your shoes in your closet. While using that dead space behind your door, it holds your shoes on display to easily find the pair that you are looking for. It saves time while also protecting your investment. Heavy-duty construction and triple hooks mean that they will last for years. Hooks are compatible with most modern interior doors. Assembled Dimensions: 6.0 L x 22.0 W x 63.0 H inches.","images":["https://m.media-amazon.com/images/I/71WQzOsQGnL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Whitmor","source_asin":"B071ZFGGGY","category_path":"Home & Kitchen"},"sku":"BM-587446","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B071ZFGGGY","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B071ZFGGGY","price_pending":true,"merchant_ready":false});
